-- Current schema after all migrations in migrations.ts (reference only; migrations.ts is executed).
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, repo_url TEXT NOT NULL, base_branch TEXT NOT NULL, created_at TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', chief_agent_id TEXT REFERENCES agents(id));
CREATE TABLE IF NOT EXISTS machines (id TEXT PRIMARY KEY, name TEXT NOT NULL, token TEXT NOT NULL UNIQUE, concurrency INTEGER NOT NULL, runtimes_json TEXT NOT NULL, last_seen_at TEXT, created_at TEXT NOT NULL, models_json TEXT NOT NULL DEFAULT '{}', models_requested INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS topics (id TEXT PRIMARY KEY, title TEXT NOT NULL, runtime_session_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, project_id TEXT REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS todos (id TEXT PRIMARY KEY, number INTEGER NOT NULL UNIQUE, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, spec TEXT NOT NULL, phase TEXT NOT NULL, agent_id TEXT REFERENCES agents(id), plan_agent_id TEXT REFERENCES agents(id), mode TEXT NOT NULL, tags_json TEXT NOT NULL, created_by TEXT NOT NULL, topic_id TEXT REFERENCES topics(id), previous_gate TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, done_at TEXT);
CREATE TABLE IF NOT EXISTS builds (id TEXT PRIMARY KEY, todo_id TEXT REFERENCES todos(id), branch TEXT NOT NULL, machine_id TEXT REFERENCES machines(id), status TEXT NOT NULL, base_commit TEXT, head_commit TEXT, tokens_in INTEGER NOT NULL DEFAULT 0, tokens_out INTEGER NOT NULL DEFAULT 0, duration_ms INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, required_machine_id TEXT REFERENCES machines(id), scheduled_agent_id TEXT REFERENCES agents(id));
CREATE TABLE IF NOT EXISTS turns (id TEXT PRIMARY KEY, build_id TEXT NOT NULL REFERENCES builds(id), kind TEXT NOT NULL, status TEXT NOT NULL, machine_id TEXT REFERENCES machines(id), prompt TEXT NOT NULL, started_at TEXT, ended_at TEXT, error TEXT, tokens_in INTEGER NOT NULL DEFAULT 0, tokens_out INTEGER NOT NULL DEFAULT 0, session_state_json TEXT, stop_requested INTEGER NOT NULL DEFAULT 0, agent_snapshot_json TEXT, completion_json TEXT, duration_ms INTEGER NOT NULL DEFAULT 0, last_reported_at TEXT, not_before TEXT);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL, turn_id TEXT REFERENCES turns(id), role TEXT NOT NULL, content TEXT NOT NULL, meta_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, build_id TEXT NOT NULL REFERENCES builds(id), kind TEXT NOT NULL, version INTEGER NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(build_id, kind, version));
CREATE TABLE IF NOT EXISTS queued_messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL, content TEXT NOT NULL, delivered_at TEXT, created_at TEXT NOT NULL, source_message_id TEXT REFERENCES messages(id), delivery_turn_id TEXT REFERENCES turns(id));
CREATE TABLE IF NOT EXISTS mcp_tokens (token TEXT PRIMARY KEY, turn_id TEXT NOT NULL REFERENCES turns(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_batches (turn_id TEXT NOT NULL REFERENCES turns(id), batch_id TEXT NOT NULL, body_json TEXT NOT NULL, PRIMARY KEY(turn_id, batch_id));
CREATE TABLE IF NOT EXISTS machine_claims (machine_id TEXT NOT NULL REFERENCES machines(id) ON DELETE CASCADE, request_id TEXT NOT NULL, job_json TEXT NOT NULL, PRIMARY KEY(machine_id, request_id));
CREATE TABLE IF NOT EXISTS server_events (id INTEGER PRIMARY KEY AUTOINCREMENT, event_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS skills (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL, source_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS connections (id TEXT PRIMARY KEY, identifier TEXT UNIQUE NOT NULL, name TEXT NOT NULL, catalog_id TEXT, transport TEXT NOT NULL CHECK(transport IN ('http','stdio')), url TEXT, command TEXT, args_json TEXT NOT NULL, machine_id TEXT REFERENCES machines(id), secret_json_ciphertext TEXT NOT NULL, iv TEXT NOT NULL, tag TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS api_keys (id TEXT PRIMARY KEY, name TEXT NOT NULL, prefix TEXT NOT NULL, hash TEXT NOT NULL UNIQUE, scopes_json TEXT NOT NULL, created_at TEXT NOT NULL, last_used_at TEXT, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL, runtime TEXT NOT NULL, model TEXT NOT NULL, reasoning TEXT, avatar TEXT, is_chief INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, permissions_json TEXT NOT NULL DEFAULT '{}', default_skill_ids_json TEXT NOT NULL DEFAULT '[]', updated_at TEXT NOT NULL DEFAULT '', connection_ids_json TEXT NOT NULL DEFAULT '[]');
CREATE INDEX IF NOT EXISTS turns_queue_idx ON turns(status);
CREATE INDEX IF NOT EXISTS messages_conversation_idx ON messages(conversation_id, created_at);
CREATE INDEX IF NOT EXISTS documents_build_idx ON documents(build_id, kind, version);
CREATE INDEX IF NOT EXISTS turns_build_status_idx ON turns(build_id, status);
CREATE INDEX IF NOT EXISTS server_events_created_idx ON server_events(created_at);
CREATE UNIQUE INDEX IF NOT EXISTS topics_project_idx ON topics(project_id) WHERE project_id IS NOT NULL;
